export const OBJECT_DEFAULTS={bookPages:[],assetModel:'boombox',customModel:'',modelSurface:'',modelCredit:'',windowClosed:false,particles:false,pageLeft:'这是左页。可输入段落或替换图片。',pageRight:'这是右页。留下这一刻的故事。',disc:'',pageLeftImage:'',pageRightImage:'',windowX:.15,windowY:.12,viewScale:1,look:'card-archive',title:'',subtitle:'',kind:'card',material:'foil',light:'studio',mode:'follow',roughness:28,wear:16,tilt:8,angle: -12,pitch:5,opening:0,cropX:50,cropY:50,zoom:1,transparent:false,glass:true,source:'selected',spine:'AFTERIMAGE / SIDE A',front:'',back:''};
export function normalizeObjectConfig(raw={}){const c={...OBJECT_DEFAULTS};for(const [key,values] of Object.entries({kind:['card','cd','frame','crt','book','player','xp'],material:['matte','gloss','foil','holo'],light:['studio','window','record','night'],mode:['follow','fixed','loop'],source:['selected','group','all']}))if(values.includes(raw[key]))c[key]=raw[key];for(const [k,min,max] of [['viewScale',.65,1.45],['roughness',0,100],['wear',0,100],['tilt',0,15],['angle',-180,180],['pitch',-65,65],['opening',0,170],['windowX',0,.39],['windowY',0,.3],['cropX',0,100],['cropY',0,100],['zoom',1,3]])if(Number.isFinite(raw[k]))c[k]=Math.max(min,Math.min(max,raw[k]));for(const k of ['transparent','glass','particles','windowClosed'])if(typeof raw[k]==='boolean')c[k]=raw[k];if(typeof raw.spine==='string')c.spine=raw.spine.slice(0,4000);for(const k of ['look','title','subtitle','pageLeft','pageRight'])if(typeof raw[k]==='string')c[k]=raw[k].slice(0,4000);for(const k of ['front','back','disc','pageLeftImage','pageRightImage'])if(typeof raw[k]==='string'&&raw[k].length<16000000&&/^data:image\/(png|jpeg|webp);base64,/.test(raw[k]))c[k]=raw[k];if(Array.isArray(raw.bookPages))c.bookPages=raw.bookPages.slice(0,24).map(p=>({text:typeof p?.text==='string'?p.text.slice(0,8000):'',image:typeof p?.image==='string'&&p.image.length<16000000&&/^data:image\/(png|jpeg|webp);base64,/.test(p.image)?p.image:''}));if(['','boombox','custom'].includes(raw.assetModel))c.assetModel=raw.assetModel;if(typeof raw.customModel==='string'&&raw.customModel.length<45000000&&/^data:(model\/gltf-binary|application\/octet-stream);base64,/.test(raw.customModel))c.customModel=raw.customModel;for(const k of ['modelSurface','modelCredit'])if(typeof raw[k]==='string')c[k]=raw[k].slice(0,500);return c;}
